// ---------------------------------------------------------------------------
// WorkSense Phase 8 onboarding engine — fully deterministic, zero LLM.
//  - Task definition vs execution state (separate column groups)
//  - Strict owner matrix: employee | manager | hr | it_security (no broad HR
//    to service owners)
//  - DAG planning from the APPROVED role relationship (application ->
//    requisition), never a title substring
//  - Cycle / missing-dep validation + Kahn topological scheduling
//  - Blocked set (multiple simultaneous blockers) + critical path
//  - Honest readiness estimate (never a guarantee)
//  - plan_hash bound to canonical task definitions (approvals bind to it)
//  - Waiver, adaptation (learning -> verification, failed verification reopens
//    gap), completion checks as PURE functions so backend functions just
//    load rows and apply them.
// ---------------------------------------------------------------------------

export type OwnerRole = "employee" | "manager" | "hr" | "it_security";
export type TaskType = "learning" | "verification" | "provisioning" | "policy" | "access" | "onboarding_admin";
export type TaskState = "pending" | "blocked" | "ready" | "in_progress" | "done" | "waived" | "failed";
export type PlanStatus = "draft" | "pending_approval" | "approved" | "completed" | "superseded";

export interface WhyEvidence {
  reason: string;
  source_evidence: { source_type: string; fact: string; ref?: string }[];
}

export interface EvReq {
  kind: "note" | "assessment_id";
  label: string;
  required: boolean;
}

/** Immutable task DEFINITION — what needs to happen. */
export interface TaskDef {
  task_code: string;
  title: string;
  task_type: TaskType;
  owner_role: OwnerRole;
  required: boolean;
  non_waivable: boolean;
  depends_on: string[];
  duration_days: number;
  why_evidence: WhyEvidence;
  evidence_requirements: EvReq[];
}

export interface Blocker {
  id: string;
  note: string;
  reported_by: string;
  at: string;
  status: "open" | "resolved";
  resolved_by?: string;
  resolved_at?: string;
}

export interface Waiver {
  by_twin_id: string;
  by_name: string;
  reason: string;
  policy_basis: { doc_code: string; version: number | null } | null;
  at: string;
}

export interface CompletionRecord {
  actor_twin_id: string;
  actor_name: string;
  at: string;
  evidence: { kind: "note" | "assessment_id"; label: string; value: string }[];
  attempt_hash: string;
  note?: string;
}

export interface Adaptation {
  kind: "replaced" | "reopened_gap";
  replaced_by?: string;
  reason: string;
  source_evidence: WhyEvidence["source_evidence"];
  at: string;
  actor_twin_id: string;
}

/** Task DEFINITION + EXECUTION state. */
export interface PlanTask extends TaskDef {
  state: TaskState;
  start_date: string | null;
  due_date: string | null;
  topological_level: number;
  blocked_reasons: string[]; // task_codes of unmet deps
  blockers: Blocker[];
  waiver: Waiver | null;
  completion_record: CompletionRecord | null;
  adaptation: Adaptation | null;
}

export interface ReadinessDimension {
  key: "access" | "compliance" | "capability";
  label: string;
  /** satisfied = done (or waived for access/compliance; waived NEVER counts as
   *  capability — a waived task must not imply a skill was verified). */
  satisfied: number;
  total: number;
  pct: number;
  note: string;
}

export interface ReadinessEstimate {
  /** Overall task completion (done + waived). */
  ready_pct: number;
  satisfied: number;
  total: number;
  /** Remaining critical path, in duration-days (not node count). */
  remaining_critical_days: number;
  /** Business-day projection from today; null when blockers make it unknown. */
  projected_ready_date: string | null;
  blocked_count: number;
  note: string;
  /** True when the projection is provisional (open blockers on the path). */
  provisional: boolean;
  /** Remaining critical path as task codes (ordered, by duration). */
  critical_path: string[];
  /** Access / compliance / role-capability readiness shown separately from
   *  overall completion. */
  dimensions: ReadinessDimension[];
  working_calendar: "business_days";
}

export interface CarryoverEntry {
  task_code: string;
  from_version: number;
  from_plan_id: string;
  note: string;
}

export class CycleError extends Error {
  constructor(message = "cyclic dependency detected in onboarding plan") {
    super(message);
    this.name = "CycleError";
  }
}

// ---------------------------------------------------------------------------
// Hashing (deterministic, sync; binding approval to exact task definitions)
// ---------------------------------------------------------------------------

function fnv1a(str: string, seed = 0x811c9dc5): number {
  let h = seed >>> 0;
  for (let i = 0; i < str.length; i++) {
    h ^= str.charCodeAt(i);
    h = Math.imul(h, 0x01000193);
  }
  return h >>> 0;
}

/** Stable hash of canonical task definitions — same defs always hash equal. */
export function planHash(defs: TaskDef[]): string {
  const canonical = defs
    .map((d) =>
      JSON.stringify({
        code: d.task_code,
        title: d.title,
        type: d.task_type,
        owner: d.owner_role,
        required: d.required,
        non_waivable: d.non_waivable,
        deps: [...d.depends_on].sort(),
        days: d.duration_days,
        why: d.why_evidence,
        evreq: d.evidence_requirements,
      })
    )
    .sort()
    .join("\u0001");
  const h1 = fnv1a(canonical).toString(16).padStart(8, "0");
  const h2 = fnv1a(canonical, 0x811c9dc5 ^ canonical.length).toString(16).padStart(8, "0");
  return `${h1}${h2}`;
}

/** Attempt hash for execution dedup: same actor+payload on same task+action. */
export function attemptHash(planId: string, taskCode: string, action: string, payload: unknown): string {
  const canonical = JSON.stringify({ planId, taskCode, action, payload });
  const h1 = fnv1a(canonical).toString(16).padStart(8, "0");
  const h2 = fnv1a(canonical, 0xdeadbeef).toString(16).padStart(8, "0");
  return `${h1}${h2}`;
}

// ---------------------------------------------------------------------------
// DAG validation + topological scheduling
// ---------------------------------------------------------------------------

export function validateDag(defs: TaskDef[]): void {
  const ids = new Set(defs.map((d) => d.task_code));
  for (const d of defs) {
    for (const dep of d.depends_on) {
      if (!ids.has(dep)) throw new Error(`task ${d.task_code} depends on unknown task ${dep}`);
    }
  }
  const indegree = new Map(defs.map((d) => [d.task_code, d.depends_on.length]));
  const adj = new Map<string, string[]>();
  for (const d of defs) {
    for (const dep of d.depends_on) adj.set(dep, [...(adj.get(dep) ?? []), d.task_code]);
  }
  const queue = defs.filter((d) => (indegree.get(d.task_code) ?? 0) === 0).map((d) => d.task_code);
  const order: string[] = [];
  while (queue.length > 0) {
    const id = queue.shift()!;
    order.push(id);
    for (const child of adj.get(id) ?? []) {
      indegree.set(child, (indegree.get(child) ?? 0) - 1);
      if ((indegree.get(child) ?? 0) === 0) queue.push(child);
    }
  }
  if (order.length !== defs.length) throw new CycleError();
}

const DAY_MS = 24 * 60 * 60 * 1000;
function addDays(d: Date, days: number): Date {
  return new Date(d.getTime() + days * DAY_MS);
}

export function topologicalOrder(defs: TaskDef[]): string[] {
  validateDag(defs);
  const indegree = new Map(defs.map((d) => [d.task_code, d.depends_on.length]));
  const adj = new Map<string, string[]>();
  for (const d of defs) {
    for (const dep of d.depends_on) adj.set(dep, [...(adj.get(dep) ?? []), d.task_code]);
  }
  const queue = defs.filter((d) => (indegree.get(d.task_code) ?? 0) === 0).map((d) => d.task_code);
  const order: string[] = [];
  while (queue.length > 0) {
    const id = queue.shift()!;
    order.push(id);
    for (const child of adj.get(id) ?? []) {
      indegree.set(child, (indegree.get(child) ?? 0) - 1);
      if ((indegree.get(child) ?? 0) === 0) queue.push(child);
    }
  }
  return order;
}

/** Satisfied = done or waived. Used for both state derivation and critical path. */
export function satisfiedSet(tasks: Pick<PlanTask, "task_code" | "state">[]): Set<string> {
  return new Set(tasks.filter((t) => t.state === "done" || t.state === "waived").map((t) => t.task_code));
}

export function hasOpenBlocker(blockers: Blocker[]): boolean {
  return blockers.some((b) => b.status === "open");
}

/**
 * Recompute execution state + dates from stored facts (definition + state).
 * Dates are null for blocked/failed tasks and cascade downstream.
 */
export function deriveStates(defs: TaskDef[], facts: {
  done?: string[];
  waived?: string[];
  failed?: string[];
  blockers?: Record<string, Blocker[]>;
  approved?: boolean;
  startDate?: string;
}): PlanTask[] {
  validateDag(defs);
  const done = new Set(facts.done ?? []);
  const waived = new Set(facts.waived ?? []);
  const failed = new Set(facts.failed ?? []);
  const approved = facts.approved ?? false;
  const start = facts.startDate ? new Date(facts.startDate) : new Date();

  const order = topologicalOrder(defs);
  const defById = new Map(defs.map((d) => [d.task_code, d]));

  const level = new Map<string, number>();
  for (const id of order) {
    const d = defById.get(id)!;
    level.set(id, d.depends_on.reduce((m, dep) => Math.max(m, (level.get(dep) ?? 0) + 1), 0));
  }

  const endBy = new Map<string, Date | null>();
  const out = new Map<string, PlanTask>();
  for (const id of order) {
    const d = defById.get(id)!;
    const blockers = facts.blockers?.[id] ?? [];
    const open = hasOpenBlocker(blockers);
    const depStates = new Map(d.depends_on.map((dep) => [dep, out.get(dep)?.state ?? "missing"]));
    const unmet = d.depends_on.filter((dep) => !done.has(dep) && !waived.has(dep));
    const cascadingBlock = d.depends_on.some((dep) => {
      const s = depStates.get(dep);
      return s === "blocked" || s === "failed";
    });

    let state: TaskState = "pending";
    if (done.has(id)) state = "done";
    else if (waived.has(id)) state = "waived";
    else if (failed.has(id)) state = "failed";
    else if (!approved) state = "pending";
    else if (open) state = "blocked";
    else if (cascadingBlock) state = "blocked";
    else if (unmet.length > 0) state = "pending"; // queued: approved but deps not yet satisfied
    else state = "ready";

    let startDate: Date | null;
    let endDate: Date | null;
    if (state === "blocked" || state === "failed") {
      startDate = null;
      endDate = null;
    } else {
      const prereqEnds = d.depends_on
        .map((dep) => endBy.get(dep))
        .filter((e): e is Date => e instanceof Date);
      const base = prereqEnds.length > 0 ? new Date(Math.max(...prereqEnds.map((e) => e.getTime()))) : new Date(start);
      startDate = base;
      endDate = addDays(base, d.duration_days);
    }
    endBy.set(id, endDate);

    out.set(id, {
      ...d,
      state,
      start_date: startDate ? startDate.toISOString() : null,
      due_date: endDate ? endDate.toISOString() : null,
      topological_level: level.get(id) ?? 0,
      blocked_reasons: unmet,
      blockers,
      waiver: null,
      completion_record: null,
      adaptation: null,
    });
  }
  return [...out.values()];
}

/** Apply stored execution records onto derived states (single source of truth). */
export function materialize(tasks: PlanTask[], records: {
  completion?: Record<string, CompletionRecord>;
  waiver?: Record<string, Waiver>;
  adaptation?: Record<string, Adaptation>;
  blockers?: Record<string, Blocker[]>;
}): PlanTask[] {
  return tasks.map((t) => ({
    ...t,
    state: records.waiver?.[t.task_code]
      ? "waived"
      : records.completion?.[t.task_code]
        ? "done"
        : records.adaptation?.[t.task_code]
          ? "failed"
          : t.state,
    blockers: records.blockers?.[t.task_code] ?? t.blockers,
    waiver: records.waiver?.[t.task_code] ?? t.waiver,
    completion_record: records.completion?.[t.task_code] ?? t.completion_record,
    adaptation: records.adaptation?.[t.task_code] ?? t.adaptation,
  }));
}

// ---------------------------------------------------------------------------
// Critical path + honest readiness estimate
// ---------------------------------------------------------------------------

/** Longest remaining chain (by duration) among tasks that are not satisfied. */
export function criticalPath(defs: TaskDef[], satisfied: Set<string>): { tasks: string[]; total_days: number } {
  validateDag(defs);
  const defById = new Map(defs.map((d) => [d.task_code, d]));
  const adj = new Map<string, string[]>();
  for (const d of defs) for (const dep of d.depends_on) adj.set(dep, [...(adj.get(dep) ?? []), d.task_code]);

  const memo = new Map<string, { tasks: string[]; days: number }>();
  const chainFrom = (id: string): { tasks: string[]; days: number } => {
    const known = memo.get(id);
    if (known) return known;
    const d = defById.get(id)!;
    let best: { tasks: string[]; days: number } = { tasks: [], days: 0 };
    for (const child of adj.get(id) ?? []) {
      const c = chainFrom(child);
      if (c.days > best.days) best = c;
    }
    const res = { tasks: [id, ...best.tasks], days: d.duration_days + best.days };
    memo.set(id, res);
    return res;
  };

  let best: { tasks: string[]; days: number } = { tasks: [], days: 0 };
  for (const d of defs) {
    if (satisfied.has(d.task_code)) continue;
    const c = chainFrom(d.task_code);
    if (c.days > best.days) best = c;
  }
  return { tasks: best.tasks, total_days: best.days };
}

/** Business-day calendar: duration days map onto working days only. */
function addBusinessDays(start: Date, workingDays: number): Date {
  const d = new Date(start);
  let remaining = workingDays;
  while (remaining > 0) {
    d.setUTCDate(d.getUTCDate() + 1);
    const dow = d.getUTCDay();
    if (dow === 0 || dow === 6) continue; // weekend
    remaining -= 1;
  }
  return d;
}

/**
 * Honest readiness: overall task completion shown SEPARATELY from access,
 * compliance and role-capability readiness. The critical path uses remaining
 * durations (business days) over prerequisites — never the longest node chain.
 * Blockers on the path make the projection provisional (unknown date); waived
 * learning/verification tasks never count as capability.
 */
export function estimateReadiness(defs: TaskDef[], tasks: PlanTask[], startDate: string, now: string): ReadinessEstimate {
  const satisfied = satisfiedSet(tasks);
  const total = defs.length;
  const readyPct = total === 0 ? 0 : Math.round((satisfied.size / total) * 1000) / 10;
  const { tasks: path, total_days } = criticalPath(defs, satisfied);
  const blockedCount = tasks.filter((t) => t.state === "blocked" || t.state === "failed").length;

  // A blocker on any remaining critical-path task means the date is unknown,
  // not confidently projected — label the estimate provisional (spec: forecast
  // dates must account for blockers; label provisional estimates).
  const openOnPath = path.filter((code) => tasks.find((t) => t.task_code === code)?.blockers.some((b) => b.status === "open"));
  const provisional = openOnPath.length > 0;
  const projected = total_days === 0 ? null : provisional ? null : addBusinessDays(new Date(now), total_days).toISOString();

  const dimensionFor = (key: ReadinessDimension["key"], types: TaskType[], countWaived: boolean): ReadinessDimension => {
    const members = tasks.filter((t) => types.includes(t.task_type));
    const sat = members.filter((t) => t.state === "done" || (countWaived && t.state === "waived")).length;
    const pct = members.length === 0 ? 100 : Math.round((sat / members.length) * 1000) / 10;
    return {
      key,
      label: key === "access" ? "Access readiness" : key === "compliance" ? "Compliance readiness" : "Role capability",
      satisfied: sat,
      total: members.length,
      pct,
      note:
        key === "capability"
          ? "Waived tasks never count as verified skill — capability needs a completed learning or verification task."
          : key === "access"
            ? "Provisioning and system-access tasks complete the technical floor."
            : "Mandatory policy tasks are done before systems stay open.",
    };
  };

  const dimensions: ReadinessDimension[] = [
    dimensionFor("access", ["provisioning", "access"], true),
    dimensionFor("compliance", ["policy"], true),
    dimensionFor("capability", ["learning", "verification"], false),
  ];

  const note = provisional
    ? `Estimated readiness — ${openOnPath.length} blocker(s) remain on the critical path, so the ready date is unknown until they clear. Blocked work makes this provisional, not a guarantee.`
    : "Estimated readiness — projected earliest completion in business days from today; an estimate, not a guarantee.";

  return {
    ready_pct: readyPct,
    satisfied: satisfied.size,
    total,
    remaining_critical_days: total_days,
    projected_ready_date: projected,
    blocked_count: blockedCount,
    note,
    provisional,
    critical_path: path,
    dimensions,
    working_calendar: "business_days",
  };
}

// ---------------------------------------------------------------------------
// Authorization matrix — strict per-owner-role, no broad HR to service owners
// ---------------------------------------------------------------------------

export function canActOnTask(actor: { id: string; role: string; org_id: string | null }, taskOwner: OwnerRole, twin: { id: string; manager_id: string | null; org_id: string | null }): { ok: boolean; error?: string } {
  if (actor.org_id !== twin.org_id) return { ok: false, error: "Cross-org task access is forbidden." };
  switch (taskOwner) {
    case "employee":
      return actor.id === twin.id
        ? { ok: true }
        : { ok: false, error: "Only the employee themselves may complete this task." };
    case "manager":
      return actor.role === "manager" && actor.id === twin.manager_id
        ? { ok: true }
        : { ok: false, error: "Only the employee's direct manager may act on this task." };
    case "hr":
      return actor.role === "hr_executive" || actor.role === "hr_partner"
        ? { ok: true }
        : { ok: false, error: "Only HR may act on this task." };
    case "it_security":
      return actor.role === "it_security"
        ? { ok: true }
        : { ok: false, error: "Only the IT security service owner may act on this task — HR has no access to service-owner tasks." };
    default:
      return { ok: false, error: "Unknown owner role." };
  }
}

export function canWaive(actor: { id: string; role: string }, twin: { manager_id: string | null }, taskNonWaivable: boolean, taskOwner: OwnerRole): { ok: boolean; error?: string } {
  if (taskNonWaivable) {
    return actor.role === "hr_executive"
      ? { ok: true }
      : { ok: false, error: "Non-waivable tasks may only be waived by an HR Executive with a policy basis." };
  }
  if (actor.role === "manager" && actor.id === twin.manager_id) return { ok: true };
  if (actor.role === "hr_executive" || actor.role === "hr_partner") return { ok: true };
  return { ok: false, error: "Waivers require the employee's manager or an HR role." };
}

export function canAdapt(actor: { id: string; role: string }, twin: { manager_id: string | null }): { ok: boolean; error?: string } {
  if (actor.role === "manager" && actor.id === twin.manager_id) return { ok: true };
  if (actor.role === "hr_executive" || actor.role === "hr_partner") return { ok: true };
  return { ok: false, error: "Plan adaptation requires the employee's manager or an HR role." };
}

// ---------------------------------------------------------------------------
// Completion checks — pure; every gate the backend must enforce
// ---------------------------------------------------------------------------

export interface CompletionCheckInput {
  planStatus: PlanStatus;
  task: PlanTask;
  actor: { id: string; role: string; org_id: string | null };
  twin: { id: string; manager_id: string | null; org_id: string | null };
  evidence: { kind: "note" | "assessment_id"; label: string; value: string }[];
}

export function validateCompletion(i: CompletionCheckInput): { ok: boolean; code?: string; error?: string } {
  if (i.planStatus !== "approved") {
    return { ok: false, code: "plan_pending", error: "The plan must be approved by the Manager and HR Executive before tasks can be completed." };
  }
  const auth = canActOnTask(i.actor, i.task.owner_role, i.twin);
  if (!auth.ok) return { ok: false, code: "forbidden", error: auth.error };
  if (i.task.state === "done") {
    return { ok: false, code: "double_submission", error: `"${i.task.title}" is already complete — double submission rejected.` };
  }
  if (i.task.state === "waived") {
    return { ok: false, code: "already_waived", error: `"${i.task.title}" was waived — nothing to complete.` };
  }
  if (i.task.state === "failed") {
    return { ok: false, code: "task_failed", error: `"${i.task.title}" is failed/adopted out — regenerate the plan.` };
  }
  const open = i.task.blockers.filter((b) => b.status === "open");
  if (open.length > 0) {
    return { ok: false, code: "blocked", error: `Cannot complete — open blocker(s): ${open.map((b) => b.note).join("; ")}.` };
  }
  if (i.task.state === "blocked") {
    const why = i.task.blocked_reasons.length > 0 ? `Prerequisites not satisfied: ${i.task.blocked_reasons.join(", ")}` : "blocked by an upstream task or blocker";
    return { ok: false, code: "unmet_prerequisite", error: `Cannot complete — ${why}.` };
  }
  if (i.task.blocked_reasons.length > 0) {
    return { ok: false, code: "unmet_prerequisite", error: `Prerequisites not satisfied: ${i.task.blocked_reasons.join(", ")}.` };
  }
  if (i.task.state === "pending") {
    return { ok: false, code: "plan_pending", error: "The plan is not active yet." };
  }
  const missing = (i.task.evidence_requirements ?? []).filter((r) => r.required && !i.evidence.some((e) => e.kind === r.kind && String(e.value ?? "").trim().length > 0));
  if (missing.length > 0) {
    return { ok: false, code: "missing_evidence", error: `Evidence required before completion: ${missing.map((m) => m.label).join(", ")}.` };
  }
  return { ok: true };
}

// ---------------------------------------------------------------------------
// Waiver application (authorized actor/reason/policy basis/audit)
// ---------------------------------------------------------------------------

export interface WaiverInput {
  by_twin_id: string;
  by_name: string;
  reason: string;
  policy_basis: { doc_code: string; version: number | null } | null;
  at: string;
}

export function applyWaiver(task: PlanTask, waiver: WaiverInput): PlanTask {
  return {
    ...task,
    state: "waived",
    waiver: { ...waiver },
    completion_record: null,
  };
}

// ---------------------------------------------------------------------------
// Adaptation: learning -> verification, and failed verification reopens gap
// ---------------------------------------------------------------------------

export interface AdaptationInput {
  actor_twin_id: string;
  reason: string;
  source_evidence: WhyEvidence["source_evidence"];
  at: string;
}

/** Replace a learning task with a verification task (new assessment evidence). */
export function adaptLearningToVerification(defs: TaskDef[], learningTask: TaskDef, verifyDef: TaskDef, input: AdaptationInput): { defs: TaskDef[]; adaptation: Adaptation } {
  const adaptation: Adaptation = {
    kind: "replaced",
    replaced_by: verifyDef.task_code,
    reason: input.reason,
    source_evidence: input.source_evidence,
    at: input.at,
    actor_twin_id: input.actor_twin_id,
  };
  const rest = defs.filter((d) => d.task_code !== learningTask.task_code);
  return { defs: [...rest, verifyDef], adaptation };
}

/** Mark a verification task failed: the gap reopens and the plan must revise. */
export function failVerification(task: PlanTask, input: AdaptationInput): { task: PlanTask; adaptation: Adaptation } {
  const adaptation: Adaptation = {
    kind: "reopened_gap",
    reason: input.reason,
    source_evidence: input.source_evidence,
    at: input.at,
    actor_twin_id: input.actor_twin_id,
  };
  return { task: { ...task, state: "failed", adaptation }, adaptation };
}

// ---------------------------------------------------------------------------
// Plan builder — deterministic DAG from the approved role relationship
// ---------------------------------------------------------------------------

export interface PlanBuildInput {
  role: {
    title: string;
    required_skills: { skill: string; target_proficiency: number }[];
    future_skills: { skill: string; target_proficiency: number }[];
    seniority_level: number;
  };
  verified_skills: { name: string; proficiency: number }[];
  policy_docs: { doc_code: string; title: string }[];
  reopened_skills?: string[]; // skills whose verification failed — learn again
}

const slug = (s: string) => s.trim().toLowerCase().replace(/[^a-z0-9]+/g, "_").replace(/^_+|_+$/g, "");

function skillProficiency(verified: { name: string; proficiency: number }[], skill: string): number {
  const hit = verified.find((v) => v.name.toLowerCase() === skill.toLowerCase());
  return hit?.proficiency ?? 0;
}

/**
 * Deterministic plan: core provisioning/policy/admin + skill-gap learning tasks
 * + one verification task on the first required-skill gap + survey.
 */
export function buildPlanDefs(input: PlanBuildInput): TaskDef[] {
  const required = (input.role.required_skills ?? []).slice(0, 3);
  const future = (input.role.future_skills ?? []).slice(0, 2);
  const reopened = new Set((input.reopened_skills ?? []).map((s) => s.toLowerCase()));

  const gaps = required.filter(
    (s) => reopened.has(s.skill.toLowerCase()) || skillProficiency(input.verified_skills, s.skill) < s.target_proficiency
  );
  const futureGaps = future.filter((s) => skillProficiency(input.verified_skills, s.skill) < s.target_proficiency);

  const secPolicy = input.policy_docs.find((p) => p.doc_code === "POL-SEC");
  const defs: TaskDef[] = [
    {
      task_code: "it_provisioning",
      title: "IT & Laptop Provisioning",
      task_type: "provisioning",
      owner_role: "it_security",
      required: true,
      non_waivable: true,
      depends_on: [],
      duration_days: 1,
      why_evidence: {
        reason: "Company-issued equipment is mandatory before any system access is granted.",
        source_evidence: [{ source_type: "policy", fact: secPolicy ? `POL-SEC ${secPolicy.title} — work on company-issued devices only.` : "Equipment & Security policy — company-issued devices only." }],
      },
      evidence_requirements: [{ kind: "note", label: "Hardware & asset tag", required: true }],
    },
    {
      task_code: "security_training",
      title: "Security & Compliance Training",
      task_type: "policy",
      owner_role: "employee",
      required: true,
      non_waivable: true,
      depends_on: [],
      duration_days: 1,
      why_evidence: {
        reason: "Annual security training is required for continued system access.",
        source_evidence: [{ source_type: "policy", fact: secPolicy ? `POL-SEC ${secPolicy.title} — annual training required.` : "Equipment & Security policy — annual training required." }],
      },
      evidence_requirements: [{ kind: "note", label: "Training completion reference", required: true }],
    },
    {
      task_code: "payroll",
      title: "Direct Deposit & Payroll Setup",
      task_type: "onboarding_admin",
      owner_role: "hr",
      required: true,
      non_waivable: true,
      depends_on: [],
      duration_days: 0.5,
      why_evidence: {
        reason: "Payroll setup is handled by HR before the first pay run.",
        source_evidence: [{ source_type: "onboarding_admin", fact: "Standard onboarding payroll step." }],
      },
      evidence_requirements: [{ kind: "note", label: "Payroll reference (HR)", required: true }],
    },
    {
      task_code: "access_sso",
      title: "System Access & SSO Enrollment",
      task_type: "access",
      owner_role: "it_security",
      required: true,
      non_waivable: true,
      depends_on: ["it_provisioning", "security_training"],
      duration_days: 0.5,
      why_evidence: {
        reason: "SSO and tool access can only be provisioned after hardware and security training are complete.",
        source_evidence: [{ source_type: "policy", fact: "POL-SEC — MFA mandatory on all accounts; access requires completed security training." }],
      },
      evidence_requirements: [{ kind: "note", label: "MFA / SSO enrollment reference", required: true }],
    },
    {
      task_code: "team_intro",
      title: "Team Introduction & Codebase Walkthrough",
      task_type: "onboarding_admin",
      owner_role: "manager",
      required: true,
      non_waivable: false,
      depends_on: ["access_sso"],
      duration_days: 1,
      why_evidence: {
        reason: "Manager-led introduction and codebase walkthrough require system access first.",
        source_evidence: [{ source_type: "manager", fact: "Standard team integration step after access." }],
      },
      evidence_requirements: [{ kind: "note", label: "Walkthrough held (manager)", required: true }],
    },
  ];

  const firstGap = gaps[0];
  for (const s of gaps) {
    const isReopened = reopened.has(s.skill.toLowerCase());
    const code = isReopened ? `learn_${slug(s.skill)}_reopen` : `learn_${slug(s.skill)}`;
    defs.push({
      task_code: code,
      title: isReopened ? `Re-learning: ${s.skill} (verified gap re-opened)` : `First contribution using ${s.skill}`,
      task_type: "learning",
      owner_role: "employee",
      required: true,
      non_waivable: false,
      depends_on: ["team_intro"],
      duration_days: 1,
      why_evidence: {
        reason: isReopened
          ? `A prior verification attempt did not confirm ${s.skill} at target ${s.target_proficiency}; the gap is re-opened for learning.`
          : `Role requires ${s.skill} at ${s.target_proficiency}; current verified proficiency is ${skillProficiency(input.verified_skills, s.skill)}.`,
        source_evidence: [
          { source_type: "role_fit", fact: `Gap on ${s.skill} vs approved role ${input.role.title} (target ${s.target_proficiency}).` },
          ...(isReopened ? [{ source_type: "verification", fact: `Previous verification of ${s.skill} failed — reason preserved on the superseded task.` }] : []),
        ],
      },
      evidence_requirements: [{ kind: "note", label: `Contribution evidence: ${s.skill}`, required: true }],
    });
    // Verification task on the FIRST gap only.
    if (firstGap && s.skill.toLowerCase() === firstGap.skill.toLowerCase()) {
      defs.push({
        task_code: `verify_${slug(s.skill)}`,
        title: `Verification: ${s.skill} mastery assessment`,
        task_type: "verification",
        owner_role: "employee",
        required: true,
        non_waivable: false,
        depends_on: [code],
        duration_days: 0.5,
        why_evidence: {
          reason: `New assessment evidence replaces further learning for ${s.skill}: verify mastery at target ${s.target_proficiency}.`,
          source_evidence: [{ source_type: "assessment", fact: `Assessment evidence supersedes the learning-only path for ${s.skill}.` }],
        },
        evidence_requirements: [{ kind: "assessment_id", label: "Assessment evidence id", required: true }],
      });
    }
  }
  for (const s of futureGaps) {
    const anchor = gaps[0] ? `learn_${slug(gaps[0].skill)}` : "team_intro";
    defs.push({
      task_code: `future_${slug(s.skill)}`,
      title: `Upskilling plan: ${s.skill}`,
      task_type: "learning",
      owner_role: "employee",
      required: true,
      non_waivable: false,
      depends_on: [anchor],
      duration_days: 1,
      why_evidence: {
        reason: `Future skill ${s.skill} is part of the role's growth path; current verified proficiency ${skillProficiency(input.verified_skills, s.skill)} is below target ${s.target_proficiency}.`,
        source_evidence: [{ source_type: "role_fit", fact: `Future-fit gap on ${s.skill} vs approved role ${input.role.title}.` }],
      },
      evidence_requirements: [{ kind: "note", label: `Upskilling evidence: ${s.skill}`, required: true }],
    });
  }
  defs.push({
    task_code: "survey",
    title: "Onboarding Feedback Survey",
    task_type: "onboarding_admin",
    owner_role: "employee",
    required: true,
    non_waivable: false,
    depends_on: [gaps.length > 0 ? `learn_${slug(gaps[0].skill)}` : "team_intro"],
    duration_days: 0.5,
    why_evidence: {
      reason: "Feedback survey closes the loop after the core journey is underway.",
      source_evidence: [{ source_type: "onboarding_admin", fact: "Standard closing step." }],
    },
    evidence_requirements: [{ kind: "note", label: "Survey submitted", required: true }],
  });
  return defs;
}

// ---------------------------------------------------------------------------
// Carryover on regeneration: preserve valid completed work with a mapping
// ---------------------------------------------------------------------------

export function buildCarryover(prevTasks: PlanTask[], newDefs: TaskDef[], fromPlanId: string, fromVersion: number): { tasks: PlanTask[]; entries: CarryoverEntry[] } {
  const byCode = new Map(prevTasks.map((t) => [t.task_code, t]));
  const entries: CarryoverEntry[] = [];
  const tasks: PlanTask[] = newDefs.map((d) => {
    const prev = byCode.get(d.task_code);
    const fresh: PlanTask = { ...d, state: "pending", start_date: null, due_date: null, topological_level: 0, blocked_reasons: [], blockers: [], waiver: null, completion_record: null, adaptation: null };
    if (!prev) return fresh;
    const defSame =
      prev.title === d.title &&
      prev.task_type === d.task_type &&
      prev.owner_role === d.owner_role &&
      prev.required === d.required &&
      prev.non_waivable === d.non_waivable &&
      prev.duration_days === d.duration_days &&
      JSON.stringify([...prev.depends_on].sort()) === JSON.stringify([...d.depends_on].sort());
    if (!defSame) return fresh;
    if (prev.state === "done" && prev.completion_record) {
      entries.push({ task_code: d.task_code, from_version: fromVersion, from_plan_id: fromPlanId, note: "Completed work preserved on regeneration." });
      return { ...d, state: "done", start_date: prev.start_date, due_date: prev.due_date, topological_level: 0, blocked_reasons: [], blockers: [], waiver: prev.waiver, completion_record: prev.completion_record, adaptation: prev.adaptation };
    }
    if (prev.state === "waived" && prev.waiver) {
      entries.push({ task_code: d.task_code, from_version: fromVersion, from_plan_id: fromPlanId, note: "Waiver preserved on regeneration." });
      return { ...d, state: "waived", start_date: prev.start_date, due_date: prev.due_date, topological_level: 0, blocked_reasons: [], blockers: [], waiver: prev.waiver, completion_record: null, adaptation: prev.adaptation };
    }
    return fresh;
  });
  return { tasks, entries };
}


// Shared helper: after an authoritative domain transition, schedule the
// idempotent notification generator (notify-scan). Non-blocking by design —
// the response is returned immediately while the scan completes in the
// background. Failures are swallowed: notifications are derived from durable
// canonical state and the next scan would catch up; the transition itself is
// never rolled back because a notification could not be sent.
//
// NOTE: this module must stay free of `Deno` references so the plain shared
// typecheck (tsconfig.functions.json, node types) stays green. Callers pass
// their own runtime env values.
export async function notifyScanAfter(
  orgId: string,
  supabaseUrl: string,
  serviceKey: string
): Promise<void> {
  try {
    await fetch(`${supabaseUrl}/functions/v1/notify-scan`, {
      method: "POST",
      headers: {
        Authorization: `Bearer ${serviceKey}`,
        apikey: serviceKey,
        "Content-Type": "application/json",
      },
      body: JSON.stringify({ org_id: orgId }),
    });
  } catch {
    /* non-fatal */
  }
}


import { createClient } from "https://esm.sh/@supabase/supabase-js@2.39.0";



const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
};

const json = (body: unknown, status = 200) =>
  new Response(JSON.stringify(body), { status, headers: { ...corsHeaders, "Content-Type": "application/json" } });

function rowToTask(r: Record<string, unknown>): PlanTask {
  return {
    task_code: String(r.task_code),
    title: String(r.title),
    task_type: r.task_type as PlanTask["task_type"],
    owner_role: r.owner_role as PlanTask["owner_role"],
    required: Boolean(r.required),
    non_waivable: Boolean(r.non_waivable),
    depends_on: (r.depends_on ?? []) as string[],
    duration_days: Number(r.duration_days),
    why_evidence: r.why_evidence as PlanTask["why_evidence"],
    evidence_requirements: (r.evidence_requirements ?? []) as PlanTask["evidence_requirements"],
    state: r.state as PlanTask["state"],
    start_date: (r.due_date as string | null) ?? null,
    due_date: (r.due_date as string | null) ?? null,
    topological_level: Number(r.topological_level ?? 0),
    blocked_reasons: [],
    blockers: (r.blockers ?? []) as Blocker[],
    waiver: r.waiver as PlanTask["waiver"],
    completion_record: r.completion_record as CompletionRecord | null,
    adaptation: r.adaptation as Adaptation | null,
  };
}

function recompute(defs: TaskDef[], facts: {
  done: string[]; waived: string[]; failed: string[]; blockers: Record<string, Blocker[]>;
  completion: Record<string, CompletionRecord>; waiver: Record<string, WaiverInput>;
  adaptation: Record<string, Adaptation>;
}, startDate: string, now: string) {
  const tasks = materialize(
    deriveStates(defs, { approved: true, startDate, done: facts.done, waived: facts.waived, failed: facts.failed, blockers: facts.blockers }),
    { completion: facts.completion, waiver: facts.waiver, adaptation: facts.adaptation, blockers: facts.blockers }
  );
  const readiness = estimateReadiness(defs, tasks, startDate, now);
  return { tasks, readiness };
}

/** Best-effort audit insert — the action itself never fails because logging fails. */
async function logEvent(supabase, row: Record<string, unknown>): Promise<{ error?: { message?: string } } | null> {
  try {
    return await supabase.from("onboarding_task_events").insert(row);
  } catch {
    return null;
  }
}

/** Persist recomputed states for EVERY task row (downstream states cascade). */
async function syncTasks(supabase, orgId: string, planId: string, version: number, tasks: PlanTask[]): Promise<void> {
  for (const t of tasks) {
    await supabase
      .from("onboarding_tasks")
      .update({
        state: t.state,
        due_date: t.due_date,
        topological_level: t.topological_level,
        blockers: t.blockers,
        completion_record: t.completion_record,
        waiver: t.waiver,
        adaptation: t.adaptation,
      })
      .eq("org_id", orgId)
      .eq("plan_id", planId)
      .eq("version", version)
      .eq("task_code", t.task_code);
  }
}

Deno.serve(async (req) => {
  if (req.method === "OPTIONS") return new Response("ok", { headers: corsHeaders });

  const supabase = createClient(
    Deno.env.get("SUPABASE_URL")!,
    Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!
  );

  try {
    return await handle(supabase, req);
  } catch (err) {
    console.error("onboarding-task unhandled:", err);
    return json({ error: "INTERNAL", message: err instanceof Error ? `${err.name}: ${err.message}` : String(err) }, 500);
  }
});

async function handle(supabase: ReturnType<typeof createClient>, req: Request): Promise<Response> {
  const authHeader = req.headers.get("Authorization") ?? "";
  const { data: userData } = await supabase.auth.getUser(authHeader.replace("Bearer ", ""));
  const uid = userData?.user?.id;
  if (!uid) return json({ error: "UNAUTHENTICATED" }, 401);

  const { data: caller } = await supabase
    .from("digital_twins")
    .select("id, role, email, org_id, name")
    .eq("auth_user_id", uid)
    .maybeSingle();
  if (!caller) return json({ error: "UNAUTHENTICATED" }, 401);

  let body: {
    plan_id?: string; task_code?: string; action?: string; evidence?: { kind: string; label: string; value: string }[];
    note?: string; blocker_id?: string; waiver?: { reason?: string; policy_basis?: { doc_code?: string; version?: number | null } | null };
    skill?: string; source_evidence?: { source_type: string; fact: string; ref?: string }[];
  } = {};
  try {
    body = await req.json();
  } catch {
    /* empty */
  }
  const planId = (body.plan_id ?? "").trim();
  const taskCode = (body.task_code ?? "").trim();
  const action = body.action ?? "";
  if (!planId || !taskCode || !["complete", "block", "resolve", "waive", "adapt", "fail"].includes(action)) {
    return json({ error: "VALIDATION_ERROR", message: "plan_id, task_code and action (complete|block|resolve|waive|adapt|fail) are required." }, 400);
  }

  const { data: plan, error: planErr } = await supabase
    .from("onboarding_plans")
    .select("id, org_id, twin_id, version, plan_hash, status, start_date, readiness, audit_events")
    .eq("id", planId)
    .maybeSingle();
  if (planErr || !plan) return json({ error: "NOT_FOUND" }, 404);
  if (plan.org_id !== caller.org_id) return json({ error: "FORBIDDEN" }, 403);

  const { data: twin, error: twinErr } = await supabase
    .from("digital_twins")
    .select("id, name, manager_id, org_id, verified_skills, seniority_level")
    .eq("id", plan.twin_id)
    .maybeSingle();
  if (twinErr || !twin) return json({ error: "NOT_FOUND" }, 404);

  const { data: taskRows } = await supabase
    .from("onboarding_tasks")
    .select("*")
    .eq("plan_id", planId);
  const allTasks = ((taskRows ?? []) as Record<string, unknown>[]).map(rowToTask);
  const target = allTasks.find((t) => t.task_code === taskCode);
  if (!target) return json({ error: "NOT_FOUND", message: "Task not found in this plan version." }, 404);

  // All mutating actions require an active (dual-approved) plan — blockers,
  // waivers and adaptations are execution-time decisions.
  if (plan.status !== "approved") {
    return json({ error: "CONFLICT", code: "plan_pending", message: "The plan must be approved by the Manager and HR Executive before tasks can be changed." }, 400);
  }

  const startDate = plan.start_date as string;
  const now = new Date().toISOString();

  const factsOf = (tasks: PlanTask[]) => ({
    done: tasks.filter((t) => t.state === "done").map((t) => t.task_code),
    waived: tasks.filter((t) => t.state === "waived").map((t) => t.task_code),
    failed: tasks.filter((t) => t.state === "failed").map((t) => t.task_code),
    blockers: Object.fromEntries(tasks.filter((t) => t.blockers.length > 0).map((t) => [t.task_code, t.blockers])),
    completion: Object.fromEntries(tasks.filter((t) => t.completion_record).map((t) => [t.task_code, t.completion_record!])),
    waiver: Object.fromEntries(tasks.filter((t) => t.waiver).map((t) => [t.task_code, t.waiver!])),
    adaptation: Object.fromEntries(tasks.filter((t) => t.adaptation).map((t) => [t.task_code, t.adaptation!])),
  });

  const defsOf = (tasks: PlanTask[]): TaskDef[] =>
    tasks.map((t) => ({
      task_code: t.task_code,
      title: t.title,
      task_type: t.task_type,
      owner_role: t.owner_role,
      required: t.required,
      non_waivable: t.non_waivable,
      depends_on: t.depends_on,
      duration_days: t.duration_days,
      why_evidence: t.why_evidence,
      evidence_requirements: t.evidence_requirements,
    }));

  const appendAudit = (note: string, extra: Record<string, unknown> = {}) =>
    [...((plan.audit_events as unknown[]) ?? []), { actor: caller.email ?? uid, action, note, timestamp: now, ...extra }];

  // -------------------------------------------------------------------------
  // COMPLETE — server-side completion checks + genuine evidence + dedup
  // -------------------------------------------------------------------------
  if (action === "complete") {
    if (plan.status !== "approved") {
      return json({ error: "CONFLICT", code: "plan_pending", message: "The plan must be approved by the Manager and HR Executive before tasks can be completed." }, 400);
    }
    const evidence = (body.evidence ?? []).map((e) => ({
      kind: e.kind as "note" | "assessment_id",
      label: e.label,
      value: String(e.value ?? "").trim(),
    }));
    const check = validateCompletion({
      planStatus: plan.status,
      task: target,
      actor: { id: caller.id, role: caller.role, org_id: caller.org_id },
      twin: { id: twin.id, manager_id: twin.manager_id, org_id: twin.org_id },
      evidence,
    });
    if (!check.ok) {
      const ah = attemptHash(planId, taskCode, action, { evidence, note: body.note });
      await logEvent(supabase, {
        org_id: plan.org_id, plan_id: planId, task_code: taskCode, actor_twin_id: caller.id,
        action, attempt_hash: ah, result: "rejected", note: check.error, evidence: { evidence, note: body.note },
      });
      return json({ error: "CONFLICT", code: check.code ?? "CONFLICT", message: check.error }, 400);
    }

    const ah = attemptHash(planId, taskCode, action, { evidence, note: body.note });
    const completion: CompletionRecord = {
      actor_twin_id: caller.id,
      actor_name: caller.name ?? caller.email ?? caller.id,
      at: now,
      evidence,
      attempt_hash: ah,
      note: body.note ? String(body.note).trim() : undefined,
    };
    // Dedup: the same payload on the same task is a double submission.
    const { error: evErr } = await logEvent(supabase, {
      org_id: plan.org_id, plan_id: planId, task_code: taskCode, actor_twin_id: caller.id,
      action, attempt_hash: ah, result: "applied", note: "Task completed with evidence.", evidence: { evidence, note: body.note },
    });
    if (evErr) {
      return json({ error: "CONFLICT", code: "double_submission", message: "This completion was already recorded (duplicate attempt hash)." }, 400);
    }

    const facts = factsOf(allTasks);
    facts.done.push(taskCode);
    facts.completion[taskCode] = completion;
    const { tasks: next, readiness } = recompute(defsOf(allTasks), facts, startDate, now);

    await syncTasks(supabase, plan.org_id, planId, plan.version, next);
    await supabase
      .from("onboarding_plans")
      .update({ readiness, audit_events: appendAudit(`${twin.name} completed "${target.title}" with evidence.`) })
      .eq("id", planId);

    // Authoritative transition → schedule idempotent notification generation.
  void notifyScanAfter(plan.org_id, Deno.env.get("SUPABASE_URL")!, Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!);
  return json({ ok: true, action, task_code: taskCode, state: "done", readiness, completion });
  }

  // -------------------------------------------------------------------------
  // BLOCK — report an open blocker (multiple allowed)
  // -------------------------------------------------------------------------
  if (action === "block") {
    const auth = canActOnTask({ id: caller.id, role: caller.role, org_id: caller.org_id }, target.owner_role, { id: twin.id, manager_id: twin.manager_id, org_id: twin.org_id });
    if (!auth.ok && caller.role !== "hr_executive") return json({ error: "FORBIDDEN", message: auth.error }, 403);
    const note = String(body.note ?? "").trim() || "Blocker reported.";
    const blocker: Blocker = { id: crypto.randomUUID(), note, reported_by: caller.email ?? caller.id, at: now, status: "open" };
    const facts = factsOf(allTasks);
    facts.blockers[taskCode] = [...(facts.blockers[taskCode] ?? []), blocker];
    const { tasks: next, readiness } = recompute(defsOf(allTasks), facts, startDate, now);
    await syncTasks(supabase, plan.org_id, planId, plan.version, next);
    await supabase
      .from("onboarding_plans")
      .update({ readiness, audit_events: appendAudit(`Blocker on "${target.title}": ${note}`) })
      .eq("id", planId);
    await supabase.from("onboarding_task_events").insert({
      org_id: plan.org_id, plan_id: planId, task_code: taskCode, actor_twin_id: caller.id,
      action, attempt_hash: attemptHash(planId, taskCode, action, { note, blocker_id: blocker.id }), result: "applied", note, evidence: { blocker_id: blocker.id },
    });
  // Authoritative transition → schedule idempotent notification generation.
  void notifyScanAfter(plan.org_id, Deno.env.get("SUPABASE_URL")!, Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!);
    return json({ ok: true, action, task_code: taskCode, state: next.find((t) => t.task_code === taskCode)!.state, blockers: next.find((t) => t.task_code === taskCode)!.blockers, readiness });
  }

  // -------------------------------------------------------------------------
  // RESOLVE — resolve ONE open blocker; others stay
  // -------------------------------------------------------------------------
  if (action === "resolve") {
    const blockerId = (body.blocker_id ?? "").trim();
    if (!blockerId) return json({ error: "VALIDATION_ERROR", message: "blocker_id is required to resolve a blocker." }, 400);
    const auth = canActOnTask({ id: caller.id, role: caller.role, org_id: caller.org_id }, target.owner_role, { id: twin.id, manager_id: twin.manager_id, org_id: twin.org_id });
    const isSupervisor = caller.role === "manager" && twin.manager_id === caller.id;
    const isHR = caller.role === "hr_executive" || caller.role === "hr_partner";
    if (!auth.ok && !isSupervisor && !isHR) return json({ error: "FORBIDDEN", message: auth.error }, 403);

    const blockers = target.blockers;
    const idx = blockers.findIndex((b) => b.id === blockerId);
    if (idx === -1) return json({ error: "NOT_FOUND", message: "Blocker not found on this task." }, 404);
    if (blockers[idx].status !== "open") return json({ error: "CONFLICT", message: "Blocker is already resolved." }, 409);
    const resolvedBlocker = { ...blockers[idx], status: "resolved" as const, resolved_by: caller.name ?? caller.email ?? caller.id, resolved_at: now };
    const nextBlockers = blockers.map((b) => (b.id === blockerId ? resolvedBlocker : b));

    const facts = factsOf(allTasks);
    facts.blockers[taskCode] = nextBlockers;
    const { tasks: next, readiness } = recompute(defsOf(allTasks), facts, startDate, now);
    await syncTasks(supabase, plan.org_id, planId, plan.version, next);
    await supabase
      .from("onboarding_plans")
      .update({ readiness, audit_events: appendAudit(`Blocker resolved on "${target.title}" by ${caller.name ?? caller.email}.`) })
      .eq("id", planId);
    await logEvent(supabase, {
      org_id: plan.org_id, plan_id: planId, task_code: taskCode, actor_twin_id: caller.id,
      action, attempt_hash: attemptHash(planId, taskCode, action, { blocker_id: blockerId }), result: "applied", note: "Blocker resolved.", evidence: { blocker_id: blockerId },
    });
  // Authoritative transition → schedule idempotent notification generation.
  void notifyScanAfter(plan.org_id, Deno.env.get("SUPABASE_URL")!, Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!);
    return json({ ok: true, action, task_code: taskCode, state: next.find((t) => t.task_code === taskCode)!.state, blockers: nextBlockers, readiness });
  }

  // -------------------------------------------------------------------------
  // WAIVE — authorized actor + reason + policy basis + audit + recompute
  // -------------------------------------------------------------------------
  if (action === "waive") {
    const waiverAuth = canWaive(
      { id: caller.id, role: caller.role },
      { manager_id: twin.manager_id },
      target.non_waivable,
      target.owner_role
    );
    if (!waiverAuth.ok) return json({ error: "FORBIDDEN", message: waiverAuth.error }, 403);
    const reason = String(body.waiver?.reason ?? "").trim();
    if (!reason) return json({ error: "VALIDATION_ERROR", message: "A waiver reason is required." }, 400);
    let policyBasis: { doc_code: string; version: number | null } | null = null;
    if (body.waiver?.policy_basis?.doc_code) {
      const docCode = body.waiver.policy_basis.doc_code.trim();
      const { data: docRow } = await supabase
        .from("policy_documents")
        .select("doc_code, version")
        .eq("org_id", plan.org_id)
        .eq("doc_code", docCode)
        .order("version", { ascending: false })
        .limit(1);
      const doc = (docRow ?? [])[0];
      if (!doc) return json({ error: "VALIDATION_ERROR", message: `Policy basis ${docCode} does not exist.` }, 400);
      policyBasis = { doc_code: doc.doc_code, version: doc.version as number | null };
    } else if (target.non_waivable) {
      return json({ error: "VALIDATION_ERROR", message: "A non-waivable task waiver requires a policy basis citation." }, 400);
    }

    const waiver: WaiverInput = {
      by_twin_id: caller.id,
      by_name: caller.name ?? caller.email ?? caller.id,
      reason,
      policy_basis: policyBasis,
      at: now,
    };
    const facts = factsOf(allTasks);
    facts.waived.push(taskCode);
    facts.waiver[taskCode] = waiver;
    const { tasks: next, readiness } = recompute(defsOf(allTasks), facts, startDate, now);
    await syncTasks(supabase, plan.org_id, planId, plan.version, next);
    await supabase
      .from("onboarding_plans")
      .update({ readiness, audit_events: appendAudit(`${twin.name}: "${target.title}" waived — ${reason}${policyBasis ? ` (policy ${policyBasis.doc_code})` : ""}.`) })
      .eq("id", planId);
    await logEvent(supabase, {
      org_id: plan.org_id, plan_id: planId, task_code: taskCode, actor_twin_id: caller.id,
      action, attempt_hash: attemptHash(planId, taskCode, action, { reason, policy_basis: policyBasis }), result: "applied", note: reason, evidence: { reason, policy_basis: policyBasis },
    });
  // Authoritative transition → schedule idempotent notification generation.
  void notifyScanAfter(plan.org_id, Deno.env.get("SUPABASE_URL")!, Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!);
    return json({ ok: true, action, task_code: taskCode, state: "waived", waiver, readiness });
  }

  // -------------------------------------------------------------------------
  // ADAPT — new assessment evidence: learning task -> verification task
  // -------------------------------------------------------------------------
  if (action === "adapt") {
    const adaptAuth = canAdapt({ id: caller.id, role: caller.role }, { manager_id: twin.manager_id });
    if (!adaptAuth.ok) return json({ error: "FORBIDDEN", message: adaptAuth.error }, 403);
    if (target.task_type !== "learning") {
      return json({ error: "VALIDATION_ERROR", message: "Only learning tasks can be adapted into a verification task." }, 400);
    }
    const skill = String(body.skill ?? "").trim();
    if (!skill) return json({ error: "VALIDATION_ERROR", message: "skill is required to build the verification task." }, 400);
    const reason = String(body.note ?? "").trim() || `New assessment evidence covers ${skill}; verification replaces further learning.`;
    const sourceEvidence = (body.source_evidence ?? []).length > 0
      ? (body.source_evidence ?? [])
      : [{ source_type: "assessment", fact: `Assessment evidence for ${skill}.` }];

    // Rebuild defs: drop the learning task, add a verification task in its place
    // and re-point anything that depended on it.
    const oldCode = target.task_code;
    const newCode = `verify_${oldCode.replace(/^learn_/, "")}`;
    // The verification task must not already exist for that skill (plan builder
    // already adds one for the first gap).
    if (allTasks.some((t) => t.task_code === newCode)) {
      return json({ error: "CONFLICT", message: `A verification task "${newCode}" already exists in this plan — nothing to adapt.` }, 409);
    }
    const oldDefs = defsOf(allTasks);
    const verifyDef: TaskDef = {
      task_code: newCode,
      title: `Verification: ${skill} mastery assessment`,
      task_type: "verification",
      owner_role: "employee",
      required: true,
      non_waivable: false,
      depends_on: target.depends_on,
      duration_days: 0.5,
      why_evidence: {
        reason,
        source_evidence: sourceEvidence,
      },
      evidence_requirements: [{ kind: "assessment_id", label: "Assessment evidence id", required: true }],
    };
    const newDefs = oldDefs
      .filter((d) => d.task_code !== oldCode)
      .map((d) => (d.depends_on.includes(oldCode) ? { ...d, depends_on: d.depends_on.map((x) => (x === oldCode ? newCode : x)) } : d))
      .concat(verifyDef);

    const adaptation: Adaptation = { kind: "replaced", replaced_by: newCode, reason, source_evidence: sourceEvidence, at: now, actor_twin_id: caller.id };
    // Regenerate: new version + hash, approvals invalidated, completed work carried.
    const carried = buildCarryover(allTasks, newDefs, plan.id, plan.version);
    const hash = planHash(newDefs);
    const facts = factsOf(carried.tasks);
    const { tasks: next, readiness } = recompute(newDefs, facts, startDate, now);
    const newVersion = plan.version + 1;

    await supabase.from("onboarding_plans").update({ status: "superseded" }).eq("id", planId);
    const { data: newPlan } = await supabase.from("onboarding_plans").insert({
      org_id: plan.org_id, twin_id: twin.id, application_id: null, version: newVersion, plan_hash: hash,
      status: "pending_approval", manager_approval: null, hr_approval: null, start_date: startDate, generated_at: now,
      readiness, carryover: carried.entries,
      audit_events: [{ actor: caller.email ?? uid, action: "plan_adapted", note: `Learning task "${target.title}" adapted to verification (${skill}) — approvals invalidated, plan v${newVersion}.`, timestamp: now }],
    }).select("id").single();

    await supabase.from("onboarding_tasks").insert(
      next.map((t) => ({
        org_id: plan.org_id, plan_id: newPlan!.id, version: newVersion, task_code: t.task_code, title: t.title,
        task_type: t.task_type, owner_role: t.owner_role, required: t.required, non_waivable: t.non_waivable,
        depends_on: t.depends_on, duration_days: t.duration_days, due_date: t.due_date, topological_level: t.topological_level,
        why_evidence: t.why_evidence, evidence_requirements: t.evidence_requirements, state: t.state,
        completion_record: t.completion_record, blockers: t.blockers, waiver: t.waiver,
        adaptation: t.task_code === newCode ? adaptation : t.adaptation,
      }))
    );

    await logEvent(supabase, {
      org_id: plan.org_id, plan_id: newPlan!.id, task_code: oldCode, actor_twin_id: caller.id,
      action, attempt_hash: attemptHash(planId, oldCode, action, { skill }), result: "applied", note: reason, evidence: { skill, replaced_by: newCode, source_evidence: sourceEvidence },
    });

  // Authoritative transition → schedule idempotent notification generation.
  void notifyScanAfter(plan.org_id, Deno.env.get("SUPABASE_URL")!, Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!);
    return json({ ok: true, action, task_code: oldCode, replaced_by: newCode, plan_id: newPlan!.id, version: newVersion, status: "pending_approval", plan_hash: hash, readiness });
  }

  // -------------------------------------------------------------------------
  // FAIL — verification failed: reopen the gap and revise the plan
  // -------------------------------------------------------------------------
  if (action === "fail") {
    const adaptAuth = canAdapt({ id: caller.id, role: caller.role }, { manager_id: twin.manager_id });
    if (!adaptAuth.ok) return json({ error: "FORBIDDEN", message: adaptAuth.error }, 403);
    if (target.task_type !== "verification") {
      return json({ error: "VALIDATION_ERROR", message: "Only verification tasks can be failed (reopening the gap)." }, 400);
    }
    const reason = String(body.note ?? "").trim() || "Verification did not confirm the skill at target — gap re-opened.";
    const sourceEvidence = (body.source_evidence ?? []).length > 0
      ? (body.source_evidence ?? [])
      : [{ source_type: "verification", fact: reason }];
    const skill = String(body.skill ?? "").trim() || target.title.replace(/^Verification:\s*/, "").replace(/ mastery assessment$/, "");

    // Revised defs: failed verification task is retired; a re-learning task is
    // added in its place (gap re-opened), dependents re-pointed.
    const oldCode = target.task_code;
    const reopenCode = `learn_${skill.trim().toLowerCase().replace(/[^a-z0-9]+/g, "_").replace(/^_+|_+$/g, "")}_reopen`;
    const oldDefs = defsOf(allTasks);
    const reopenDef: TaskDef = {
      task_code: reopenCode,
      title: `Re-learning: ${skill} (verified gap re-opened)`,
      task_type: "learning",
      owner_role: "employee",
      required: true,
      non_waivable: false,
      depends_on: target.depends_on,
      duration_days: 1,
      why_evidence: {
        reason: `Verification of ${skill} failed — the gap is re-opened for learning.`,
        source_evidence: sourceEvidence,
      },
      evidence_requirements: [{ kind: "note", label: `Contribution evidence: ${skill}`, required: true }],
    };
    const newDefs = oldDefs
      .filter((d) => d.task_code !== oldCode)
      .map((d) => (d.depends_on.includes(oldCode) ? { ...d, depends_on: d.depends_on.map((x) => (x === oldCode ? reopenCode : x)) } : d))
      .concat(reopenDef);

    const adaptation: Adaptation = { kind: "reopened_gap", reason, source_evidence: sourceEvidence, at: now, actor_twin_id: caller.id };
    const carried = buildCarryover(allTasks, newDefs, plan.id, plan.version);
    const hash = planHash(newDefs);
    const facts = factsOf(carried.tasks);
    const { tasks: next, readiness } = recompute(newDefs, facts, startDate, now);
    const newVersion = plan.version + 1;

    await supabase.from("onboarding_plans").update({ status: "superseded" }).eq("id", planId);
    const { data: newPlan } = await supabase.from("onboarding_plans").insert({
      org_id: plan.org_id, twin_id: twin.id, application_id: null, version: newVersion, plan_hash: hash,
      status: "pending_approval", manager_approval: null, hr_approval: null, start_date: startDate, generated_at: now,
      readiness, carryover: carried.entries,
      audit_events: [{ actor: caller.email ?? uid, action: "plan_revised", note: `Verification "${target.title}" failed — gap for ${skill} re-opened; plan v${newVersion} pending approval.`, timestamp: now }],
    }).select("id").single();

    await supabase.from("onboarding_tasks").insert(
      next.map((t) => ({
        org_id: plan.org_id, plan_id: newPlan!.id, version: newVersion, task_code: t.task_code, title: t.title,
        task_type: t.task_type, owner_role: t.owner_role, required: t.required, non_waivable: t.non_waivable,
        depends_on: t.depends_on, duration_days: t.duration_days, due_date: t.due_date, topological_level: t.topological_level,
        why_evidence: t.why_evidence, evidence_requirements: t.evidence_requirements, state: t.state,
        completion_record: t.completion_record, blockers: t.blockers, waiver: t.waiver,
        adaptation: t.task_code === reopenCode ? null : t.adaptation,
      }))
    );

    await logEvent(supabase, {
      org_id: plan.org_id, plan_id: newPlan!.id, task_code: oldCode, actor_twin_id: caller.id,
      action, attempt_hash: attemptHash(planId, oldCode, action, { skill }), result: "applied", note: reason, evidence: { skill, reopened_by: reopenCode, source_evidence: sourceEvidence },
    });

  // Authoritative transition → schedule idempotent notification generation.
  void notifyScanAfter(plan.org_id, Deno.env.get("SUPABASE_URL")!, Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!);
    return json({ ok: true, action, task_code: oldCode, reopened_by: reopenCode, plan_id: newPlan!.id, version: newVersion, status: "pending_approval", plan_hash: hash, readiness });
  }

  return json({ error: "VALIDATION_ERROR", message: "Unknown action." }, 400);
}
